#include "functions.h"

#include <windows.h>
#include <bcrypt.h>
#include <wincrypt.h>

#include <limits>
#include <stdexcept>

namespace
{
    constexpr unsigned long long ITERATIONS = 600000;
}

/**
 * @brief Generates cryptographically secure random bytes.
 * @param size Number of bytes to generate.
 * @return Generated bytes.
 * @throws std::runtime_error If generation fails.
 */
Bytes randomBytes(std::size_t size)
{
    if (size == 0 ||
        size > (std::numeric_limits<ULONG>::max)())
    {
        throw std::runtime_error(" ");
    }

    Bytes data(size);

    NTSTATUS status = BCryptGenRandom(
        nullptr,
        data.data(),
        static_cast<ULONG>(data.size()),
        BCRYPT_USE_SYSTEM_PREFERRED_RNG
    );

    if (status < 0)
    {
        throw std::runtime_error(" ");
    }

    return data;
}

/**
 * @brief Derives a password hash using PBKDF2-HMAC-SHA256.
 * @param password Original password.
 * @param salt Random account salt.
 * @return Derived password hash.
 * @throws std::runtime_error If hashing fails.
 */
std::array<unsigned char, HASH_SIZE> hashing(
    const std::string& password,
    const std::array<unsigned char, SALT_SIZE>& salt)
{
    if (password.size() > (std::numeric_limits<ULONG>::max)())
    {
        throw std::runtime_error(" ");
    }

    BCRYPT_ALG_HANDLE algorithm = nullptr;

    NTSTATUS status = BCryptOpenAlgorithmProvider(
        &algorithm,
        BCRYPT_SHA256_ALGORITHM,
        nullptr,
        BCRYPT_ALG_HANDLE_HMAC_FLAG
    );

    if (status < 0)
    {
        throw std::runtime_error(" ");
    }

    std::array<unsigned char, HASH_SIZE> hash{};

    status = BCryptDeriveKeyPBKDF2(
        algorithm,
        reinterpret_cast<PUCHAR>(
            const_cast<char*>(password.data())
            ),
        static_cast<ULONG>(password.size()),
        const_cast<PUCHAR>(salt.data()),
        static_cast<ULONG>(salt.size()),
        ITERATIONS,
        hash.data(),
        static_cast<ULONG>(hash.size()),
        0
    );

    BCryptCloseAlgorithmProvider(algorithm, 0);

    if (status < 0)
    {
        throw std::runtime_error(" ");
    }

    return hash;
}

/**
 * @brief Compares two hashes without an early exit.
 * @param first First hash.
 * @param second Second hash.
 * @return True if both hashes are equal.
 */
bool compareHash(
    const std::array<unsigned char, HASH_SIZE>& first,
    const std::array<unsigned char, HASH_SIZE>& second)
{
    unsigned int difference = 0;

    for (std::size_t i = 0; i < first.size(); ++i)
    {
        difference |= first[i] ^ second[i];
    }

    return difference == 0;
}

/**
 * @brief Encrypts text using Windows DPAPI.
 * @param text Plain text.
 * @return Encrypted bytes.
 * @throws std::runtime_error If encryption fails.
 */
Bytes encryptData(const std::string& text)
{
    if (text.empty() ||
        text.size() > (std::numeric_limits<DWORD>::max)())
    {
        throw std::runtime_error(" ");
    }

    DATA_BLOB input{};
    input.pbData = reinterpret_cast<BYTE*>(
        const_cast<char*>(text.data())
        );
    input.cbData = static_cast<DWORD>(text.size());

    DATA_BLOB output{};

    if (!CryptProtectData(
        &input,
        L"Lab5 personal data",
        nullptr,
        nullptr,
        nullptr,
        CRYPTPROTECT_UI_FORBIDDEN,
        &output))
    {
        throw std::runtime_error(" ");
    }

    Bytes result;

    try
    {
        result.assign(
            output.pbData,
            output.pbData + output.cbData
        );
    }
    catch (...)
    {
        LocalFree(output.pbData);
        throw;
    }

    LocalFree(output.pbData);

    return result;
}

/**
 * @brief Decrypts bytes using Windows DPAPI.
 * @param data Encrypted bytes.
 * @return Decrypted text.
 * @throws std::runtime_error If decryption fails.
 */
std::string decryptData(const Bytes& data)
{
    if (data.empty() ||
        data.size() > (std::numeric_limits<DWORD>::max)())
    {
        throw std::runtime_error(" ");
    }

    DATA_BLOB input{};
    input.pbData = const_cast<BYTE*>(data.data());
    input.cbData = static_cast<DWORD>(data.size());

    DATA_BLOB output{};

    if (!CryptUnprotectData(
        &input,
        nullptr,
        nullptr,
        nullptr,
        nullptr,
        CRYPTPROTECT_UI_FORBIDDEN,
        &output))
    {
        throw std::runtime_error(" ");
    }

    std::string result;

    try
    {
        result.assign(
            reinterpret_cast<const char*>(output.pbData),
            output.cbData
        );
    }
    catch (...)
    {
        SecureZeroMemory(output.pbData, output.cbData);
        LocalFree(output.pbData);
        throw;
    }

    SecureZeroMemory(output.pbData, output.cbData);
    LocalFree(output.pbData);

    return result;
}